export function spiralOrder(matrix            )           {
const out         =[];let top=0,bottom=matrix.length-1,left=0,right=(matrix[0]?.length??0)-1;while(top<=bottom&&left<=right){for(let c=left;c<=right;c++)out.push(matrix[top][c]);top++;for(let r=top;r<=bottom;r++)out.push(matrix[r][right]);right--;if(top<=bottom){for(let c=right;c>=left;c--)out.push(matrix[bottom][c]);bottom--;}if(left<=right){for(let r=bottom;r>=top;r--)out.push(matrix[r][left]);left++;}}return out;
}

